// 递归回溯枚举所有符合条件的组合
void DFS(int index, vector<int>& tmp, vector<string>& res, int count, vector<int>& ans) {
    if (tmp.size() >= count) {
        res.push_back(join(tmp));
    }
    // 递归回溯
    for (int i = index; i < ans.size(); i++) {
        // 去重 剪枝
        if (i > 0 && ans[i] == ans[i-1]) {
            continue;
        }
        tmp.push_back(ans[i]);
        DFS(i + 1, tmp, res, count, ans);
        tmp.pop_back();
    }
}
