    getline(cin, input);
    vector<int> ans = split(input, ",");
    int count;
    cin >> count;
    // 升序排序
    sort(ans.begin(), ans.end());
    vector<string> res;
    vector<int> tmp;
    DFS(0, tmp, res, count, ans);
    // 排序
    sort(res.begin(), res.end());
​
