public class Main {
    // 用于拼接组合
    static String join(List<Integer> list) {
        StringBuilder sb = new StringBuilder();
        for (int num : list) {
            sb.append(num).append(",");
        }
        sb.setLength(sb.length() - 1); // 去除最后一个逗号
        return sb.toString();
    }
​
    // 递归回溯
    static void dfs(int index, List<Integer> tmp, List<String> res, int count, List<Integer> ans) {
        if (tmp.size() >= count) {
            res.add(join(tmp));
        }
        for (int i = index; i < ans.size(); i++) {
            if (i > index && ans.get(i).equals(ans.get(i - 1))) {
                continue; // 去重
            }
            tmp.add(ans.get(i));
            dfs(i + 1, tmp, res, count, ans);
            tmp.remove(tmp.size() - 1);
        }
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] strNums = sc.nextLine().split(",");
        int minCount = Integer.parseInt(sc.nextLine());
​
        List<Integer> nums = new ArrayList<>();
        for (String s : strNums) {
            nums.add(Integer.parseInt(s));
        }
​
        Collections.sort(nums);
        List<String> res = new ArrayList<>();
        dfs(0, new ArrayList<>(), res, minCount, nums);
​
        Collections.sort(res);
        for (String s : res) {
            System.out.println(s);
        }
    }
}
