const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on('line', line => {
    lines.push(line.trim());
​
    // 读取两行后开始处理
    if (lines.length === 2) {
        // 解析第一行：密码数字数组
        const nums = lines[0].split(',').map(Number).sort((a, b) => a - b);
​
        // 解析第二行：最小密码长度
        const minCount = parseInt(lines[1]);
​
        let res = [];
​
        // 回溯生成组合
        function dfs(index, tmp) {
            // 满足最小长度要求则记录
            if (tmp.length >= minCount) {
                res.push(tmp.join(','));
            }
​
            // 枚举剩余的数字
            for (let i = index; i < nums.length; i++) {
                // 去重剪枝
                if (i > index && nums[i] === nums[i - 1]) continue;
​
                tmp.push(nums[i]);        // 选择当前数字
                dfs(i + 1, tmp);          // 递归搜索
                tmp.pop();                // 回溯撤销
            }
        }
​
        // 启动回溯搜索
        dfs(0, []);
​
        // 字典序排序输出
        res.sort();
        res.forEach(r => console.log(r));
​
        rl.close();
    }
});
