package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 递归回溯函数，生成所有长度大于等于 count 的不重复组合
func dfs(index int, tmp []int, res *[]string, count int, nums []int) {
    // 如果当前组合长度符合要求，加入结果
    if len(tmp) >= count {
        var strArr []string
        for _, v := range tmp {
            strArr = append(strArr, strconv.Itoa(v))
        }
        *res = append(*res, strings.Join(strArr, ","))
    }
​
    // 回溯遍历每一个可能的组合
    for i := index; i < len(nums); i++ {
        // 跳过重复数字（剪枝）
        if i > index && nums[i] == nums[i-1] {
            continue
        }
        tmp = append(tmp, nums[i])
        dfs(i+1, tmp, res, count, nums)
        tmp = tmp[:len(tmp)-1] // 回溯
    }
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取第一行：密码数字列表（以逗号分隔）
    scanner.Scan()
    line := scanner.Text()
    numStrs := strings.Split(line, ",")
​
    // 转换为整数列表
    var nums []int
    for _, s := range numStrs {
        n, _ := strconv.Atoi(s)
        nums = append(nums, n)
    }
​
    // 读取第二行：最小密码长度
    scanner.Scan()
    count, _ := strconv.Atoi(scanner.Text())
​
    // 排序确保字典序输出
    sort.Ints(nums)
​
    var res []string
    // 回溯生成所有合法组合
    dfs(0, []int{}, &res, count, nums)
​
    // 对组合按字典序排序
    sort.Strings(res)
​
    // 输出每个组合
    for _, s := range res {
        fmt.Println(s)
    }
}
